def exchange(lst1, lst2):
    """This function checks if it's possible to exchange elements between
    lst1 and lst2 such that lst1 becomes entirely composed of even numbers."""
    even_elements_in_lst1 = sum(1 for num in lst1 if num % 2 == 0)
    even_elements_in_lst2 = sum(1 for num in lst2 if num % 2 == 0)

    # The total number of even elements in both lists must be at least as large as the size of lst1
    if even_elements_in_lst1 + even_elements_in_lst2 >= len(lst1):
        return "YES"
    else:
        return "NO"

from typing import List
def words_in_sentence(sentence: str) -> str:
    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        elif n == 2:
            return True
        elif n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    sentence = sentence.split()
    prime_words = [word for word in sentence if is_prime(len(word))]
    return ' '.join(prime_words)

