        # Determine the type of the value (int, float, str)
        if isinstance(num, int):
            return 'int'
        elif isinstance(num, float):
            return 'float'
        elif isinstance(num, str):
            # Handle different decimal separators
            num = num.replace(',', '.')
            try:
                return 'float' if '.' in num else 'int'
            except ValueError:
                return 'str'

    def get_larger(a, b):
        # Compare the two values and return the larger one
        a_type = get_value_type(a)
        b_type = get_value_type(b)

        if a_type == b_type:
            # Compare based on the numeric value if they are of the same type
            if a < b:
                return b
            elif a > b:
                return a
            else:
                return None
        elif a_type == 'int':
            # Compare based on the integer value if a is an integer and b is a float
            if a < int(b):
                return b
            elif a > int(b):
                return a
            else:
                return None
        elif a_type == 'float':
            # Compare based on the float value if a is a float and b is an integer
            if a < float(b):
                return b
            elif a > float(b):
                return a
            else:
                return None
        elif a_type == 'str':
            # Compare based on the string representation of the float if a is a string and b is a float
            num_a = float(is_real_num(a))
            num_b = float(is_real_num(b))
            if num_a < num_b:
                return b
            elif num_a > num_b:
                return a
            else:
                return None

    if not any([is_real_num(a), is_real_num(b)]):
        raise ValueError("Both inputs must be real numbers")

