def rounded_avg(n, m):
    if n > m:
        return -1

    sum_of_numbers = sum(range(n, m + 1))
    count_of_numbers = m - n + 1

    average = round(sum_of_numbers / count_of_numbers)

    if average >= 0: 
        return bin(average)[2:]
    else:
        return -1

def is_simple_power(x, n):
    """Returns True if a number x is a simple power of n, False otherwise."""
    if n == 1: 
        return x == 1

    i = 0
    while (n ** i <= x):
        if (n ** i == x):
            return True
        i += 1

    return False

