def convert_list_dictionary(list1, list2, list3):
    """
    Convert more than one list to nested dictionary.

    :param list1: List of keys for nested dictionaries
    :param list2: List of values for nested dictionaries
    :param list3: List of lists where each sub-list contains another nested dictionary key-value pairs
    :return: Dictionary containing the structured data
    """
    if len(list1) != len(list2) or len(list1) != len(list3):
        raise ValueError("Lists must have the same length")

    result = {}
    for i in range(len(list1)):
        nested_dict = {list2[i]: list3[i][j] for j in range(len(list3[i]))}
        result[list1[i]] = nested_dict

    return result

def unique_sublists(sublists):
    """
    Count lists within a list. Return a dictionary where every list is converted to a tuple 
    and the value of such tuple is the number of its occurrences in the original list.

    :param: Sublists is a list containing other lists.
    :return: A dictionary with tuples as keys and their counts as values.
    """
    sublist_counts = {}
    for sub in sublist_counts:
        # convert list to tuple
        tup = tuple(sub)
        if tup in sublist_counts:
            sublist_counts[tup] += 1
