    """
    Returns two words from a list of words starting with letter 'p'.

    :param words: List of strings representing words.
    :return: A tuple containing two words starting with 'p'.
    """
    for word in words:
        if word[0].lower() == 'p':
            # Find other words starting with 'p' in the same list (case-insensitive)
            matching_words = [other_word for other_word in words if other_word[:1].lower() == 'p']
