def replace_spaces(text):
    """
    Replaces all occurrences of underscores with spaces and vice versa in the given text.

    :param text: String to be processed.
    :return: Processed string with swapped spaces and underscores.
    """
    swapped_text = ''
    for char in text:
        if char == '_':
            swapped_text += ' '
        elif char == ' ':
            swapped_text += '_'
        else:
            swapped_text += char
    return swapped_text

def sum_range_list(lst, start_index, end_index):
    """
    Find the sum of numbers in a list within a specified range.

    :param lst: List of integers
    :param start_index: Starting index for the range
    :param end_index: Ending index for the range
    :return: Sum of numbers in the specified range
    """
    if not all(isinstance(i, int) for i in lst): 
        raise ValueError("List must contain only integers.")
    if not 0 <= start_index < len(lst) or not 0 <= end_index < len(lst):
        raise IndexError("Indices out of bounds.")
    return sum(lst[start_index:end_index+1])

def max_difference(tuple_list):
    """
    Find the maximum difference between available pairs in the given tuple list.

    :param tuple_list: List of tuples representing pairs (x, y)
    :return: Maximum difference found among all pairs
    """
    if not tuple_list or len(tuple_list) < 2:
        return 0

    max_diff = float('-inf')

    for i in range(len(tuple_list)):
        for j in range(i + 1, len(tuple_list)):
            max_diff = max(max_diff, abs(tuple_list[i][0] - tuple_list[j][0]))

    return max_diff

