def prime_num(num):
    """
    Checks if the given integer is a prime number.

    :param num: Integer to check
    :return: True if it's a prime number, False otherwise
    """
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

