def find_star_num(n):
    """
    Find the n'th star number.

    :param n: integer, the position of the star number in the sequence
    :return: integer, the n'th star number
    """
    if n == 1:
        return 1
    else:
        return 4 * (n - 1) + 1

def find_lucas(n):
    """
    Find the n'th Lucas number.

    :param n: integer, the position of the Lucas number to be found
    :return: integer, the n'th Lucas number
    """
    if n == 0:
        return 2
    elif n == 1:
        return 1
    else:
        a, b = 2, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b
